import React from 'react';

import { IQuestion, IQuestionDir, IQuestionSelect } from '@apps/Interview/@types/interview.types';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

interface IQuestionListItemProps extends React.HTMLAttributes<HTMLDivElement> {
  item: IQuestion;
}

const QuestionListItem: React.FC<IQuestionListItemProps> = ({ item, children }) => {
  return (
    <div className="ms-n2 ny-n3">
      <PohRow>
        <PohCol sm="8">
          <div>
            <strong className="me-2 " title={item.name}>
              {item.name}
              <sup className="text-danger">{item.isRequire && '*'}</sup>
            </strong>
            <small className="text-muted">{item.typeObject.name}</small>
            <small className="text-muted d-block">
              <em>{item.text}</em>
              <span className="ms-3">
                {(item as IQuestionDir)?.dir?.name ??
                  (item as IQuestionSelect)?.options?.map((x) => x.value).join(' • ') ??
                  ''}
              </span>
            </small>
          </div>
        </PohCol>
        <PohCol sm="4" className="text-end">
          {children}
        </PohCol>
      </PohRow>
    </div>
  );
};

export default QuestionListItem;
