import React from 'react';

import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import {
  deleteQuestion,
  getInterviewById,
  getQuestions,
  getQuestionTypes,
} from '../@services/interview.service';
import {
  IInterview,
  IQuestion,
  IQuestionType,
  IQuestionTypeObject,
} from '../@types/interview.types';
import { editInterview } from '../components/EditInterview';
import { editQuestion } from '../components/EditQuestion';
import QuestionListItem from '../components/QuestionListItem';
import {
  getEmptyQuestionDir,
  getEmptyQuestionInput,
  getEmptyQuestionSelect,
} from '../resources/interview.empty';

interface IInterviewEditPageProps {
  id_interview: number;
}

const InterviewEditPage: React.FC<IInterviewEditPageProps> = ({ id_interview }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IInterview>();
  const [questions, setQuestions] = React.useState<IQuestion[]>([]);
  const [questionTypes, setQuestionTypes] = React.useState<IQuestionTypeObject[]>([]);

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getInterviewById(id_interview);
      setData(res);
      const res1 = await getQuestions(id_interview);
      setQuestions(res1);
      const res2 = await getQuestionTypes();
      setQuestionTypes(res2);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, [id_interview]);

  React.useEffect(() => {
    load();
  }, [load]);

  const handleAddQuestion = async (typeObject: IQuestionTypeObject) => {
    const orderIndex = (questions.at(-1)?.order_index ?? questions.length) + 1;
    let newQ: IQuestion;
    if (typeObject.id === IQuestionType.Input) {
      newQ = await editQuestion(getEmptyQuestionInput(orderIndex, typeObject), id_interview);
    } else if (typeObject.id === IQuestionType.Select) {
      newQ = await editQuestion(getEmptyQuestionSelect(orderIndex, typeObject), id_interview);
    } else if (typeObject.id === IQuestionType.Dir) {
      newQ = await editQuestion(getEmptyQuestionDir(orderIndex, typeObject), id_interview);
    }

    notificationHelper.success('Вопрос добавлен');
    setQuestions((x) => [...x, newQ]);
  };

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  if (!data)
    return <PohAlert variant={AlertVariant.Danger}>Has no interview {id_interview}</PohAlert>;

  return (
    <div>
      <PohBreadcrumbs
        data={[
          { href: '/iv', text: 'Опросы' },
          { href: '/iv/' + id_interview, text: data.name, active: true },
        ]}
      />

      <PohContainer>
        <PageHeader title={data.name}>
          <PohButton
            size={ButtonSize.Small}
            onClick={async () => {
              const updated = await editInterview(data);
              notificationHelper.success('Обновлено');
              setData(updated);
            }}
          >
            Редактировать
          </PohButton>
        </PageHeader>
        <PohRow>
          <PohCol sm={4}>
            <h5>Описание</h5>
            <div dangerouslySetInnerHTML={{ __html: data.description }} />
          </PohCol>
          <PohCol sm={4}>
            <h5>Текст приветствия</h5>
            <div dangerouslySetInnerHTML={{ __html: data.hello_text }} />
          </PohCol>
          <PohCol sm={4}>
            <h5>Текст прощания</h5>
            <div dangerouslySetInnerHTML={{ __html: data.by_text }} />
          </PohCol>
        </PohRow>
        <PohRow className="mt-4">
          <PohCol sm={6}>
            <PageHeader title="Вопросы" />
          </PohCol>
          <PohCol sm={6} className="text-end">
            {questionTypes
              .filter((x) => x.id !== 3)
              .map((qt) => {
                return (
                  <PohButton
                    key={qt.id}
                    size={ButtonSize.Small}
                    variant={ButtonVariant.OutlineSuccess}
                    onClick={async () => {
                      handleAddQuestion(qt);
                    }}
                    title={qt.hint}
                    className="ms-2"
                  >
                    {qt.name}
                  </PohButton>
                );
              })}
          </PohCol>
        </PohRow>
        {!questions.length ? (
          <Empty>Нет вопросов</Empty>
        ) : (
          <PohList
            data={questions.map((q) => {
              return {
                key: q.id,
                children: (
                  <QuestionListItem item={q}>
                    <PohButton
                      icon={IconsEnum.edit}
                      size={ButtonSize.Small}
                      onClick={async () => {
                        const edited = await editQuestion(q, id_interview);
                        setQuestions((cur) => cur.map((x) => (x.id == q.id ? edited : x)));
                      }}
                    />
                    &nbsp;
                    <PohButton
                      icon={IconsEnum.trash}
                      size={ButtonSize.Small}
                      onClick={async () => {
                        const ok = await confirmModal2('Удаляем вопрос?');
                        if (ok) {
                          deleteQuestion(q.id)
                            .then(() => {
                              setQuestions((cur) => cur.filter((x) => x.id !== q.id));
                            })
                            .catch(notificationHelper.error);
                        }
                      }}
                    />
                  </QuestionListItem>
                ),
              };
            })}
          />
        )}
      </PohContainer>
    </div>
  );
};

export default InterviewEditPage;
