import React from 'react';

import { interviewDirList } from '@apps/Interview/@services/interview.service';
import { IQuestionDirParams } from '@apps/Interview/@types/interview.types';
import PageLoader from '@components/PageLoader';
import PohAlert from '@ui-kit/Alert';
import PohSelect from '@ui-kit/Select';

interface IEditQuestionDirProps {
  data: IQuestionDirParams;
  onChange: (data: IQuestionDirParams) => void;
  disabled?: boolean;
}

const EditQuestionDir: React.FC<IEditQuestionDirProps> = ({ data, onChange, disabled }) => {
  const [list, setList] = React.useState<
    {
      id: string;
      name: string;
    }[]
  >([]);
  const [isLoading, setIsLoading] = React.useState(false);
  const [err, setErr] = React.useState<Error>();

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const res = await interviewDirList();
        setList(res);
      } catch (error) {
        setErr(error as Error);
      } finally {
        setIsLoading(false);
      }
    };
    start();
  }, []);

  const handleInputChange =
    <K extends keyof IQuestionDirParams>(field: keyof IQuestionDirParams) =>
    (value: IQuestionDirParams[K]) => {
      onChange({
        ...data,
        [field]: value,
      });
    };

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert>{err.message}</PohAlert>;

  return (
    <div>
      <PohSelect
        horizontal
        required
        label="Тип поля"
        options={list.map((x) => ({ value: x.id, label: x.name }))}
        value={data.id_dir.toString()}
        onChange={(v) => handleInputChange('id_dir')(+v)}
        disabled={disabled}
      />
    </div>
  );
};

export default EditQuestionDir;
